import{_ as e,o as a,c as r,a2 as n}from"./chunks/framework.D46keoNO.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md","lastUpdated":1782870790000}'),i={name:"en/guide/index.md"};function d(s,t,o,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><strong>variable-translator</strong> is a VSCode extension that automatically detects any non-English characters (Chinese, Japanese, Korean, Russian, etc.) in file paths or selected text and translates them into properly-cased English.</p><p>Know exactly what to name something in your native language, but stuck on the English? Just type it as-is and let the extension translate it into <code>camelCase</code>, <code>snake_case</code> or any of the 8 supported naming formats.</p><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Trigger</th><th>Description</th></tr></thead><tbody><tr><td>File path translation</td><td>Create file/folder in Explorer</td><td>Detects non-English path segments and translates them on creation</td></tr><tr><td>Selection translation</td><td><code>Alt+Shift+T</code></td><td>Translates and replaces the selected text</td></tr><tr><td>Translate &amp; copy</td><td><code>Alt+Shift+C</code></td><td>Writes the translation in multiple formats to the clipboard history</td></tr><tr><td>Undo translation</td><td><code>Alt+Shift+Z</code> / <code>Ctrl+Z</code></td><td>Undoes a file translation within 1 minute and cleans up created directories (Ctrl+Z only when focus is outside text input areas)</td></tr><tr><td>File translation toggle</td><td><code>Alt+Shift+D</code></td><td>Quickly enables/disables file path translation</td></tr><tr><td>Switch service</td><td><code>Alt+Shift+S</code></td><td>Switches between 7 translation services</td></tr></tbody></table><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><ul><li><strong>Automatic language detection</strong>: no source language needed — any non-English characters are recognized</li><li><strong>8 naming formats</strong>: camelCase, PascalCase, snake_case, CONSTANT_CASE, param-case, Header-Case, Capital Case, no case</li><li><strong>Multiple translation services</strong>: OpenAI, Google Translate, Bing/Azure, DeepLX, Baidu, Tencent and Pinyin</li><li><strong>Automatic fallback</strong>: failed services fall back by priority, ending with Pinyin — translation never fails</li><li><strong>Timeout protection</strong>: a global 10-second translation timeout keeps the editor responsive</li><li><strong>Zero configuration</strong>: the default Pinyin service works out of the box, no API key required</li></ul><h2 id="supported-languages" tabindex="-1">Supported Languages <a class="header-anchor" href="#supported-languages" aria-label="Permalink to &quot;Supported Languages&quot;">​</a></h2><p>The extension automatically detects and translates the following languages into English:</p><table tabindex="0"><thead><tr><th>Language</th><th>Example</th></tr></thead><tbody><tr><td>Chinese</td><td>用户名称 → userName</td></tr><tr><td>Japanese</td><td>ユーザー名 → userName</td></tr><tr><td>Korean</td><td>사용자 이름 → userName</td></tr><tr><td>Russian</td><td>Имя пользователя → userName</td></tr><tr><td>Others</td><td>Any non-English characters</td></tr></tbody></table><h2 id="naming-formats" tabindex="-1">Naming Formats <a class="header-anchor" href="#naming-formats" aria-label="Permalink to &quot;Naming Formats&quot;">​</a></h2><h3 id="file-translation-formats" tabindex="-1">File Translation Formats <a class="header-anchor" href="#file-translation-formats" aria-label="Permalink to &quot;File Translation Formats&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Format</th><th>Example</th><th>Description</th></tr></thead><tbody><tr><td>camelCase</td><td>userName</td><td>Lower camel case</td></tr><tr><td>PascalCase</td><td>UserName</td><td>Upper camel case</td></tr><tr><td>snake_case</td><td>user_name</td><td>Underscore-separated, lowercase</td></tr><tr><td>CONSTANT_CASE</td><td>USER_NAME</td><td>Underscore-separated, uppercase</td></tr><tr><td>param-case</td><td>user-name</td><td>Hyphen-separated, lowercase</td></tr><tr><td>Header-Case</td><td>User-Name</td><td>Hyphen-separated, capitalized</td></tr></tbody></table><h3 id="additional-formats-for-selection-translation" tabindex="-1">Additional Formats for Selection Translation <a class="header-anchor" href="#additional-formats-for-selection-translation" aria-label="Permalink to &quot;Additional Formats for Selection Translation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Format</th><th>Example</th><th>Description</th></tr></thead><tbody><tr><td>Capital Case</td><td>User Name</td><td>Space-separated, capitalized</td></tr><tr><td>no case</td><td>user name</td><td>Space-separated, lowercase</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/hias-variable-translator/en/guide/quickstart">Quick Start</a> - Install and get started</li><li><a href="/hias-variable-translator/en/guide/features">Features</a> - Learn each feature in detail</li><li><a href="/hias-variable-translator/en/guide/config">Configuration</a> - Full configuration reference</li><li><a href="/hias-variable-translator/en/guide/services">Translation Services</a> - Sign up and configure each service</li></ul>',17)])])}const g=e(i,[["render",d]]);export{p as __pageData,g as default};
